type libwinit_EventType = EventType
type libwinit_EventTouchPhase = EventTouchPhase
type libwinit_EventMouseScrollDeltaType = EventMouseScrollDeltaType
type libwinit_MouseScrollDelta = MouseScrollDelta
type libwinit_EventMouseButtonType = EventMouseButtonType
type libwinit_EventMouseButton = EventMouseButton
type libwinit_EventInputElementState = EventInputElementState
type libwinit_UserEvent = UserEvent
type libwinit_U128 = U128
type libwinit_TouchEvent = TouchEvent
type libwinit_MouseWheelEvent = MouseWheelEvent
type libwinit_MouseInputEvent = MouseInputEvent
type libwinit_CursorMovedEvent = CursorMovedEvent
type libwinit_EventKeyboardInput = EventKeyboardInput
type libwinit_EventReceivedCharacter = EventReceivedCharacter
type libwinit_WindowResizedEvent = WindowResizedEvent
type libwinit_WindowScaleFactorChangedEvent = WindowScaleFactorChangedEvent
type libwinit_WindowMovedEvent = WindowMovedEvent
type libwinit_WindowFocusedEvent = WindowFocusedEvent
type libwinit_WindowOccludedEvent = WindowOccludedEvent
type libwinit_EventModifiersState = EventModifiersState
type libwinit_EventUserEvent = EventUserEvent
